    @Test
    void testParseSkillFromZipWithBlankSkillMd() throws IOException {
        // Given: zip where SKILL.md exists but is empty/blank
        byte[] zipBytes = createZipWithBlankSkillMd();

        // When & Then
        NacosApiException exception = assertThrows(NacosApiException.class,
            () -> SkillZipParser.parseSkillFromZip(zipBytes, "test-namespace"));
        // The file WAS found; the error should NOT say "not found"
        assertFalse(exception.getMessage().contains("not found"),
            "Error message should not say 'not found' when SKILL.md exists but is blank: " + exception.getMessage());
        // The error should indicate the file is blank/empty
        assertTrue(exception.getMessage().toLowerCase().contains("blank")
            || exception.getMessage().toLowerCase().contains("empty"),
            "Error message should indicate blank/empty content: " + exception.getMessage());
    }

