    }

    @Test
    void testGetPluginPropertiesReturnsEmptyForUnknownType() {
        Properties properties = configChangeConfigs.getPluginProperties("notRegistered");
        assertNotNull(properties);
        assertTrue(properties.isEmpty());
        assertNull(properties.getProperty("enabled"));
    }

    @Test
    void testRefreshPluginPropertiesIgnoresMalformedPropertyWithoutDot() {
        // Create a fresh ConfigChangeConfigs with no valid properties loaded first.
        MockEnvironment emptyEnv = new MockEnvironment();
        EnvUtil.setEnvironment(emptyEnv);

        // Mock PropertiesUtil to return Properties containing both a valid key
        // ("mockPlugin.enabled") and a malformed one without any dot ("nodotvalue").
        // When the loop hits "nodotvalue", indexOf('.') returns -1, and
        // substring(0, -1) throws StringIndexOutOfBoundsException. The exception
        // is caught, but the assignment `configPluginProperties = newProperties` at line 67
        // is inside the try block BEFORE the catch, so all valid entries are lost.
        Properties badProperties = new Properties();
        badProperties.setProperty("mockPlugin.enabled", "true");
        badProperties.setProperty("nodotvalue", "bad");

        try (MockedStatic<PropertiesUtil> mocked = Mockito.mockStatic(PropertiesUtil.class)) {
            mocked.when(() -> PropertiesUtil.getPropertiesWithPrefix(Mockito.any(),
                    Mockito.eq(ConfigChangeConstants.NACOS_CORE_CONFIG_PLUGIN_PREFIX)))
                .thenReturn(badProperties);

            // Create a brand new instance so its constructor's refreshPluginProperties()
            // runs with the mocked badProperties — no prior valid data to fall back on.
            ConfigChangeConfigs freshConfigs = new ConfigChangeConfigs();

            // Valid property "mockPlugin.enabled" must survive despite the malformed "nodotvalue"
            // causing StringIndexOutOfBoundsException. If the bug exists, the exception prevents
            // the assignment of configPluginProperties, so valid properties are wiped out.
            assertTrue(Boolean.parseBoolean(
                freshConfigs.getPluginProperties("mockPlugin").getProperty("enabled")),
                "Valid property 'mockPlugin.enabled' should still be loaded even when "
                + "a malformed property without dot ('nodotvalue') causes StringIndexOutOfBoundsException");
        }
    }

    @Test
    void testRefreshPluginPropertiesIgnoresPropertyLoadingException() {
        try (MockedStatic<PropertiesUtil> mocked = Mockito.mockStatic(PropertiesUtil.class)) {
            mocked.when(() -> PropertiesUtil.getPropertiesWithPrefix(environment,
                ConfigChangeConstants.NACOS_CORE_CONFIG_PLUGIN_PREFIX))
                .thenThrow(new RuntimeException("failed"));

            configChangeConfigs.onEvent(ServerConfigChangeEvent.newEvent());
        }

        assertTrue(configChangeConfigs.getPluginProperties("mockPlugin")
            .containsKey("enabled"));
    }

    @Test
    void testGetPluginPropertiesNeverReturnsNullDuringConcurrentRefresh()
        throws InterruptedException {
        // Reproduces the check-then-act race: previously `getPluginProperties` reloaded
        // the field between `containsKey` and `get`, so if a refresh swapped in a map
        // missing the key in between, `get` returned null and the method propagated null.
        // The fix reads the field once and treats a null lookup as the empty-properties
        // branch. Two environments are alternated: one with the probe key, one without.
        int readerThreads = 8;
        int durationMillis = 300;
        String pluginType = "raceProbePlugin";
        String pluginEnabledKey = "nacos.core.config.plugin." + pluginType + ".enabled";
        MockEnvironment withKey = new MockEnvironment();
        withKey.setProperty(pluginEnabledKey, "true");
        MockEnvironment withoutKey = new MockEnvironment();
        withoutKey.setProperty("nacos.core.config.plugin.otherPlugin.enabled", "true");
        CountDownLatch start = new CountDownLatch(1);
        AtomicReference<Throwable> failure = new AtomicReference<>();
        Thread[] readers = new Thread[readerThreads];
        for (int i = 0; i < readerThreads; i++) {
            readers[i] = new Thread(() -> {
                try {
                    start.await();
                    long deadline = System.currentTimeMillis() + durationMillis;
                    while (System.currentTimeMillis() < deadline) {
                        Properties properties = configChangeConfigs.getPluginProperties(pluginType);
                        if (properties == null) {
                            throw new AssertionError(
                                "getPluginProperties returned null mid-refresh");
                        }
                    }
                } catch (Throwable t) {
                    failure.compareAndSet(null, t);
                }
            }, "config-change-reader-" + i);
            readers[i].start();
        }
        Thread refresher = new Thread(() -> {
            try {
                start.await();
                long deadline = System.currentTimeMillis() + durationMillis;
                int counter = 0;
                while (System.currentTimeMillis() < deadline) {
                    EnvUtil.setEnvironment((counter++ % 2 == 0) ? withKey : withoutKey);
                    configChangeConfigs.onEvent(ServerConfigChangeEvent.newEvent());
                }
            } catch (Throwable t) {
                failure.compareAndSet(null, t);
            }
        }, "config-change-refresher");
        refresher.start();

        start.countDown();
        refresher.join(TimeUnit.SECONDS.toMillis(5));
        for (Thread reader : readers) {
            reader.join(TimeUnit.SECONDS.toMillis(5));
        }

        if (failure.get() != null) {
            throw new AssertionError("Concurrent reader observed failure", failure.get());
        }
    }

}

