    // ==================== expireLock zombie lock regression test ====================

    /**
     * Regression test: expireLock must NOT create a zombie entry when the lock does not exist.
     * Correct behavior: use showLocks().get() (like releaseLock does), which returns null
     * when the lock is absent, and then gracefully handle the missing lock.
     * 
     * The bug was that expireLock called getMutexLock() which uses computeIfAbsent,
     * creating a new empty lock even when no lock existed. These zombie entries
     * accumulate over time and waste memory.
     */
    @Test
    public void testExpireLockShouldNotCreateEntryForNonExistentLock() {
        buildService();

        // Track map size before the call
        ConcurrentHashMap<LockKey, AtomicLockService> locks = new ConcurrentHashMap<>();

        // Simulate showLocks returning empty map (lock does not exist)
        ConcurrentHashMap<LockKey, AtomicLockService> showMap = new ConcurrentHashMap<>();
        Mockito.when(lockManager.showLocks()).thenReturn(Collections.unmodifiableMap(showMap));

        // Simulate getMutexLock creating entries (the buggy behavior path)
        // If the fix is applied, getMutexLock should NOT be called for non-existent locks
        // because showLocks().get() returns null first
        Mockito.when(lockManager.getMutexLock(Mockito.any(LockKey.class)))
            .thenAnswer(invocation -> {
                LockKey key = invocation.getArgument(0);
                return locks.computeIfAbsent(key, k -> new ReentrantAtomicLock(k.getKey()));
            });

        WriteRequest request = buildExpireRequest("owner-1", "non-existent-key");
        Response response = lockOperationService.onApply(request);

        // Correct behavior: no entry should be created in the lock map
        LockKey missingKey = new LockKey(LockConstants.NACOS_LOCK_TYPE, "non-existent-key");
        assertFalse(locks.containsKey(missingKey),
            "expireLock must NOT create a zombie entry for a non-existent lock");
    }

    // ==================== expireLock 僵尸锁测试 ====================

    @Test
    public void testExpireLockCreatesZombieEntryWhenLockAlreadyRemoved() {
        buildService();
        // 模拟场景：过期扫描器读取到一个锁，但当 onApply 执行时，
        // 该锁已被移除（例如被 CLEANUP_CONNECTION 清理）。
        // expireLock 调用 getMutexLock()，该方法通过 computeIfAbsent 创建新的空锁。

        ConcurrentHashMap<LockKey, AtomicLockService> locks = new ConcurrentHashMap<>();
        // getMutexLock 在 key 不存在时会创建新锁（computeIfAbsent）
        Mockito.when(lockManager.getMutexLock(Mockito.any(LockKey.class)))
            .thenAnswer(invocation -> {
                LockKey key = invocation.getArgument(0);
                return locks.computeIfAbsent(key, k -> new ReentrantAtomicLock(k.getKey()));
            });

        WriteRequest request = buildExpireRequest("owner-1", "zombie-key");
        Response response = lockOperationService.onApply(request);
        assertTrue(response.getSuccess());

        // BUG: 虽然之前不存在锁，但 map 中创建了一个僵尸锁条目
        LockKey zombieKey = new LockKey(LockConstants.NACOS_LOCK_TYPE, "zombie-key");
        assertTrue(locks.containsKey(zombieKey),
            "expireLock 不应为不存在的锁创建条目，但产生了僵尸锁");
        AtomicLockService zombieLock = locks.get(zombieKey);
        assertTrue(zombieLock.isClear(),
            "僵尸锁应为空（无 owner）");
    }

