        assertTrue(properties.isEnabled());
        assertTrue(properties.isLegacyMcpImportApiEnabled());
        assertFalse(properties.isAllowUserUrl());
        assertEquals(2000, properties.getDefaultConnectTimeoutMillis());
        assertEquals(2048, properties.getDefaultMaxArtifactSize());
        assertEquals(1, properties.getSources().size());
        AiResourceImportSourceConfig source = properties.getSources().get(0);
        assertEquals("mcp-official", source.getSourceId());
        assertEquals("MCP Official", source.getDisplayName());
        assertEquals("official source", source.getDescription());
        assertEquals("mcp-registry", source.getPluginName());
        assertEquals(Arrays.asList("mcp", "skill"), source.getResourceTypes());
        assertEquals("https://example.com", source.getEndpoint());
        assertEquals("token-ref", source.getAuthRef());
        assertEquals(2000, source.getConnectTimeoutMillis());
        assertEquals(2048, source.getMaxArtifactSize());
        assertEquals("v0", source.getProperties().get("protocol-version"));
    }

    /**
     * When an int property is set to a non-numeric string, load() should fall back
     * to the default value rather than throw NumberFormatException.
     */
    @Test
    void loadShouldFallBackDefaultForInvalidIntValue() {
        Properties props = new Properties();
        props.setProperty(AiResourceImportProperties.PREFIX + "default-connect-timeout-ms", "not-a-number");

        AiResourceImportProperties result = assertDoesNotThrow(() ->
            AiResourceImportProperties.load(props),
            "load() should not throw NumberFormatException for invalid int property");

        assertEquals(AiResourceImportProperties.DEFAULT_CONNECT_TIMEOUT_MILLIS,
            result.getDefaultConnectTimeoutMillis(),
            "Should fall back to default when int value is invalid");
    }

    /**
     * When a long property is set to a non-numeric string, load() should fall back
     * to the default value rather than throw NumberFormatException.
     */
    @Test
    void loadShouldFallBackDefaultForInvalidLongValue() {
        Properties props = new Properties();
        props.setProperty(AiResourceImportProperties.PREFIX + "default-max-artifact-size", "abc");

        AiResourceImportProperties result = assertDoesNotThrow(() ->
            AiResourceImportProperties.load(props),
            "load() should not throw NumberFormatException for invalid long property");

        assertEquals(AiResourceImportProperties.DEFAULT_MAX_ARTIFACT_SIZE,
            result.getDefaultMaxArtifactSize(),
            "Should fall back to default when long value is invalid");
    }
}

